query getLeaves($metricId: String!, $filter: Filter) {
  leaves(metricId: $metricId, filter: $filter) {
    id
    name
    score
    improvement
    timeLost
    thresholds {
      experience
      numberOfDevices
    }
    uuid
    appType
    troubleshootUrl
    devicesInvestigationUrl
    usersInvestigationUrl
  }
}
